from typing import Tuple

def mask_sensitive_data(
    data: str, 
    data_type: str,
    mask_char: str = '*'
) -> Tuple[str, bool]:
    """
    敏感数据脱敏。
    """
    if not data:
        return '', False

    data = str(data).strip()

    if data_type == 'phone':
        # 手机号: 保留前3后4
        if len(data) == 11:
            return data[:3] + mask_char * 4 + data[-4:], True
        return data, False

    elif data_type == 'email':
        # 邮箱: 保留首字符和域名
        if '@' in data:
            local, domain = data.split('@')
            if len(local) > 1:
                masked_local = local[0] + mask_char * (len(local) - 1)
                return masked_local + '@' + domain, True
        return data, False

    elif data_type == 'id_card':
        # 身份证: 保留前6后4
        if len(data) in [15, 18]:
            return data[:6] + mask_char * (len(data) - 10) + data[-4:], True
        return data, False

    elif data_type == 'bank_card':
        # 银行卡: 保留后4位
        if len(data) >= 10:
            return mask_char * (len(data) - 4) + data[-4:], True
        return data, False

    elif data_type == 'generic':
        # 通用: 保留首尾各2个字符
        if len(data) <= 4:
            return mask_char * len(data), True
        return data[:2] + mask_char * (len(data) - 4) + data[-2:], True

    else:
        return data, False
